<script setup lang="ts">defineOptions({ inheritAttrs: false }); const props = withDefaults(defineProps<{ selected?: boolean; disabled?: boolean }>(), { selected: false }); function move(event: KeyboardEvent) { if (!['ArrowRight','ArrowLeft','Home','End'].includes(event.key)) return; const tabs = Array.from((event.currentTarget as HTMLElement).closest('[role=tablist]')?.querySelectorAll<HTMLButtonElement>('[role=tab]:not(:disabled)') ?? []); if (!tabs.length) return; const index = tabs.indexOf(event.currentTarget as HTMLButtonElement); const next = event.key === 'Home' ? 0 : event.key === 'End' ? tabs.length - 1 : (index + (event.key === 'ArrowRight' ? 1 : -1) + tabs.length) % tabs.length; event.preventDefault(); tabs[next]?.focus() }</script>
<template><button v-bind="$attrs" class="ew-tab" type="button" role="tab" :disabled="props.disabled" :aria-selected="props.selected" :tabindex="props.selected ? 0 : -1" @keydown="move"><slot /></button></template>
